import{_ as t,l as n,o,c as l,v as r,p as i,x as a,d as u,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"undo / redo 与 doublewrite","description":"","frontmatter":{"title":"undo / redo 与 doublewrite","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/undo-redo-doublewrite.md","filePath":"cs/undo-redo-doublewrite.md","lastUpdated":1789023840000}'),c={name:"cs/undo-redo-doublewrite.md"};function b(E,e,h,A,_,m){const d=n("Mermaid");return o(),l("div",null,[e[1]||(e[1]=r('<h1 id="undo-redo-与-doublewrite" tabindex="-1">undo / redo 与 doublewrite <a class="header-anchor" href="#undo-redo-与-doublewrite" aria-label="Permalink to &quot;undo / redo 与 doublewrite&quot;">​</a></h1><div class="epigraph"><p>redo 让已提交变更可重做；undo 让未提交可撤、让旧版本可读。doublewrite 先把页复制到连续区再写数据文件，对付半页撕裂。</p><footer>—— 据 Mohan et al. ARIES；Gray and Reuter；InnoDB doublewrite 设计</footer></div><p><a href="/cs/innodb-vs-postgres-storage">上一课</a>对照聚簇与堆。本课不选主键。缺口是日志角色拆开：主干 <a href="/cs/wal">WAL</a> 已给先行协议；ARIES 直觉点到 UNDO/REDO。进阶对照 InnoDB 式 redo+undo 表空间，以及为何还要 doublewrite：页写入非原子时，恢复不能对半新半旧页做物理 redo。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>steal/no-force：脏页可先于提交落盘，提交可不刷数据页。redo：前滚已提交（及已刷脏的页上未刷的日志）。undo：回滚未提交，并给 MVCC 读旧版（InnoDB）。Postgres 堆把旧版本留在表上，undo 角色弱化，redo 仍在 WAL。缺口是<strong>页撕裂</strong>：4KB 原子写、16KB 页，断电可写到一半。checksum 失败后，若无完好副本，物理 redo 无法套在烂页上。</p><p>doublewrite：先把待写页批量写到共享 doublewrite 区（连续、较小），fsync，再写真正表空间。恢复时发现数据页坏则从 doublewrite 取。这是介质路径，不是另一种隔离。</p><p><span class="marginnote">ARIES 生理日志假定页要么旧要么已应用到某 LSN。撕裂打破假定。有的文件系统提供原子写或 reflink，可关 doublewrite。本课机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>InnoDB：redo 环文件；undo 段存旧行版本与回滚链。Postgres：WAL redo；堆上行版本+vacuum 回收。两者都要检查点限定 redo 起点。模糊检查点后课。</p><p>关闭 doublewrite 只在确认页原子写时。压缩/加密页同样要撕裂保护。</p>',10)),(o(),i(p,null,{default:a(()=>[s(d,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOD%5B%22%E6%94%B9%E9%A1%B5%22%5D%20--%3E%20REDO%5B%22%E5%85%88%E5%86%99%20redo%22%5D%0A%20%20MOD%20--%3E%20UNDO%5B%22undo%20%E6%97%A7%E5%83%8F%20%2F%20%E6%88%96%E5%A0%86%E4%B8%8A%E6%97%A7%E7%89%88%22%5D%0A%20%20FLUSH%5B%22%E5%88%B7%E6%95%B0%E6%8D%AE%E9%A1%B5%22%5D%20--%3E%20DW%5B%22%E5%85%88%20doublewrite%22%5D%0A%20%20DW%20--%3E%20DATA%5B%22%E5%86%8D%E5%86%99%E8%A1%A8%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MVCC 读：InnoDB 可能沿 undo 链回溯；Postgres 在堆上看 xmin/xmax。性能：undo 链过长像索引回表放大——后课 GC。doublewrite 增加顺序写，吞吐换正确性。</p><p>复制：物理复制传 redo；逻辑复制解行可能用 undo 构造前像。CDC 课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Postgres vacuum 冻结。也不把影子分页当 ARIES 替代——更后课对照。CLR 在 ARIES 三阶段课。</p><p>后课默认：redo 保提交，undo 或堆版本保回滚与旧读；撕裂用 doublewrite 或原子页。Postgres 元组版本与 vacuum：堆上 MVCC 的回收。</p><p>没有完好页，生理 redo 无处落脚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>redo 前滚，undo/堆版本回滚与旧读。</li><li>doublewrite 修复非原子页写。</li><li>Postgres vacuum 下一课：堆版本回收与冻结。</li><li>出处：ARIES；Gray and Reuter；InnoDB doublewrite。</li></ul>',9))])}const B=t(c,[["render",b]]);export{w as __pageData,B as default};
